```python
from collections import deque

def topological_sort(dependencies):
    graph = {node: set() for node in dependencies}
    for node, prereqs in dependencies.items():
        for p in prereqs:
            graph.setdefault(p, set())
            graph[node].add(p)

    indegree = {node: 0 for node in graph}
    for node, prereqs in graph.items():
        for p in prereqs:
            indegree[node] += 1

    queue = deque(n for n in graph if indegree[n] == 0)
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for other in graph:
            if node in graph[other]:
                indegree[other] -= 1
                if indegree[other] == 0:
                    queue.append(other)

    if len(order) != len(graph):
        raise ValueError("Cycle detected in dependencies")
    return order
```

Example:
```python
topological_sort({"app": ["lib", "core"], "lib": ["core"], "core": []})
# ['core', 'lib', 'app']  (or another valid order)
```

